import {balances,recentFlows,N_RATIO} from './ecology.js';
import {escape} from './views.js';
const sources={photons:{name:'光能',color:'#e8c57b'},redox:{name:'热泉化能',color:'#e3a180'},plankton:{name:'背景浮游物',color:'#92cb90'},detritus:{name:'残骸',color:'#b29e87'},radiant:{name:'辐射',color:'#baabed'}};
const number=n=>n.toLocaleString('zh-CN',{maximumFractionDigits:1});
export function ecosystemView(w,selected){
 const all=recentFlows(w),flows=selected?all.filter(f=>f.consumer===String(selected)||f.source===String(selected)):all;
 const totals=new Map();for(const f of flows)totals.set(f.consumer,(totals.get(f.consumer)||0)+f.amount);
 const consumers=[...totals].sort((a,b)=>b[1]-a[1]).slice(0,10).map(([id])=>id),chosen=flows.filter(f=>consumers.includes(f.consumer)),origins=[...new Set(chosen.map(f=>f.source))].sort((a,b)=>Number(Boolean(sources[b]))-Number(Boolean(sources[a]))||a.localeCompare(b));
 const metadata=id=>sources[id]||{name:w.species.find(s=>String(s.id)===id)?.name,color:w.species.find(s=>String(s.id)===id)?.color};
 const h=Math.max(340,Math.max(origins.length,consumers.length)*60+72),position=(id,ids)=>54+(ids.indexOf(id)+.5)*(h-80)/Math.max(1,ids.length),max=Math.max(1,...chosen.map(f=>f.amount));
 const connections=chosen.map(f=>{const y1=position(f.source,origins),y2=position(f.consumer,consumers),color=metadata(f.source).color;return `<path d="M190 ${y1} C320 ${y1},350 ${y2},482 ${y2}" fill="none" stroke="${color}" stroke-opacity=".44" stroke-width="${1.4+Math.sqrt(f.amount/max)*17}"><title>${escape(metadata(f.source).name)} → ${escape(metadata(f.consumer).name)}：${number(f.amount)} 能量</title></path>`;}).join('');
 const labels=(ids,left)=>ids.map(id=>{const m=metadata(id),y=position(id,ids),total=chosen.filter(f=>(left?f.source:f.consumer)===id).reduce((sum,f)=>sum+f.amount,0);return `<g ${sources[id]?'':`data-eco-species="${id}" role="button" tabindex="0" aria-label="筛选 ${escape(m.name)}"`}><rect x="${left?12:482}" y="${y-22}" width="178" height="44" rx="6" fill="#182b2c" stroke="${m.color}" stroke-opacity=".65"/><text x="${left?24:494}" y="${y-2}" fill="${m.color}" font-size="14">${escape(m.name)}</text><text x="${left?24:494}" y="${y+15}" fill="#9db7ad" font-size="11">${number(total)} 能量</text></g>`;}).join('');
 const b=balances(w),pools=['nutrient','redox','plankton','detritus'].map(k=>w.fields.reduce((sum,f)=>sum+f[k],0));
 const living=w.species.filter(s=>s.count>0),total=living.reduce((n,s)=>n+s.count,0),effective=total?Math.exp(-living.reduce((h,s)=>h+(s.count/total)*Math.log(s.count/total),0)):0;
 const capture=all.filter(f=>!sources[f.source]).reduce((n,f)=>n+f.amount,0),foodTotal=all.reduce((n,f)=>n+f.amount,0),e=w.ecology;
 const selectedName=selected?w.species.find(s=>s.id===selected)?.name:'整个世界';
 const roles=living.map(s=>{const intake=all.filter(f=>f.consumer===String(s.id)),sum=intake.reduce((v,f)=>v+f.amount,0),production=intake.filter(f=>['photons','redox','radiant'].includes(f.source)).reduce((v,f)=>v+f.amount,0),p=sum?production/sum:0;return {s,sum,p};}).sort((a,b)=>b.sum-a.sum);
 const roleTable=`<section class="eco-panel"><div class="section-heading"><h2>各谱系怎样获得能量</h2><span class="muted">按实际摄入判定</span></div><p>生产表示利用光或化学能源合成有机物；消费表示摄入已有有机物。同一谱系可以同时承担两种作用。</p><div class="eco-role-legend"><span>● 生产供能</span><span>● 消费供能</span></div><div class="eco-roles">${roles.map(({s,sum,p})=>`<button data-eco-species="${s.id}" class="eco-role ${s.id===selected?'selected':''}"><span style="color:${s.color}">${escape(s.name)}<small>${sum?(p>.9?'主要生产':p<.1?'主要消费':'混合营养'):'尚无摄入记录'} · ${s.count} 个体</small></span><span class="eco-role-bar ${sum?'':'no-record'}"><i style="width:${p*100}%"></i></span><strong>${Math.round(p*100)}% / ${sum?Math.round((1-p)*100):0}%</strong></button>`).join('')||'<p>等待生命诞生。</p>'}</div></section>`;

 return `<div class="view-intro"><div><span class="eyebrow">ENERGY / LIFE / RETURN</span><h2>每一次摄食，都连接着别的生命</h2><p>观察资源流向、营养循环与种群之间实际发生的关系。</p></div></div>
 <div class="eco-metrics"><article><span>分群多样性</span><strong>${effective.toFixed(2)}</strong><small>${living.length} 个存续分群 · 同时考虑数量均匀度</small></article><article><span>捕食供能占比</span><strong>${foodTotal?(capture/foodTotal*100).toFixed(1):'0.0'}<small>%</small></strong><small>来自近期实际摄食记录</small></article><article><span>养分再循环</span><strong>${number(e.recycled*N_RATIO)}</strong><small>残骸累计释放的抽象养分</small></article></div>
 <section class="eco-panel"><div class="section-heading"><h2>食物与能源网络</h2><span class="muted">${escape(selectedName)} ${selected?'<button class="text-button" data-eco-species="all">全部谱系 ↗</button>':''}</span></div><p>从左侧食物指向右侧种群。线宽表示摄入量；较早记录按 600 时步的尺度逐渐衰减。点击右侧谱系可筛选。</p><div class="foodweb-scroll"><svg class="foodweb" viewBox="0 0 672 ${h}" role="img" aria-label="实际摄入能量构成的食物网"><text x="12" y="24" fill="#9db7ad" font-size="12">食物 / 能源</text><text x="482" y="24" fill="#9db7ad" font-size="12">获得能量的种群</text>${connections}${labels(origins,true)}${labels(consumers,false)}${!chosen.length?'<text x="336" y="170" text-anchor="middle" fill="#9db7ad" font-size="15">还没有可观测的摄食记录</text>':''}</svg></div><p class="eco-caption">显示摄入量最多的 ${consumers.length} 个种群。背景浮游物是抽象的初级生产者资源库，不计入演化种群。</p>
 <details><summary>查看实际能量转移记录 · 前 ${Math.min(36,flows.length)} / ${flows.length} 条</summary><div class="eco-flow-list">${flows.slice(0,36).map(f=>`<div><span>${escape(metadata(f.source).name)} <b>→</b> ${escape(metadata(f.consumer).name)}</span><strong>${number(f.amount)}</strong></div>`).join('')||'<p>尚无记录</p>'}</div></details></section>
 ${roleTable}<section class="eco-panel"><div class="section-heading"><h2>环境资源与循环</h2><span class="muted">当前库存 · 模型单位</span></div><div class="eco-pools">${[['溶解养分',pools[0],'合成生命需要的材料'],['化学能源',pools[1],'从热泉进入，被化能生命消耗'],['浮游有机物',pools[2],'光与养分共同驱动生长'],['残骸有机物',pools[3],'死亡与未吸收食物的去处']].map(([name,value,caption])=>`<article><span>${name}</span><strong>${number(value)}</strong><small>${caption}</small></article>`).join('')}</div><div class="cycle-strip"><span>光 / 热泉 + 养分</span><b>→</b><span>生命与浮游物</span><b>→</b><span>消费者 / 残骸</span><b>→</b><span>分解 · 养分回流</span></div><p>相邻区域交换资源；海岸降低交换速度。各地季节、温度、陆海条件共同影响生存。死亡可以使竞争者获得食物，过度消耗则会让局部资源枯竭。</p></section>
 <section class="eco-panel"><div class="section-heading"><h2>收支核对</h2><span class="eco-balanced">${Math.abs(b.energyError)<.001&&Math.abs(b.nutrientError)<.001?'收支相符':'需要检查'}</span></div><div class="eco-ledger"><span>初始能量库存<strong>${number(e.initial.energy)}</strong></span><span>已吸收 / 注入能量<strong>${number(e.energyIn)}</strong></span><span>累计散热<strong>${number(e.heat)}</strong></span><span>边界流出能量<strong>${number(e.energyOut)}</strong></span><span>当前能量库存<strong>${number(b.energy)}</strong></span></div><details><summary>模型假设与核对误差</summary><p>当前库存 = 初始库存 + 外部输入 − 散热 − 边界流出。所有有机物使用统一养分比例 0.035。储能、身体结构、浮游物和残骸都纳入库存；出生结构由亲代支付。能量误差 ${b.energyError.toExponential(2)}，养分误差 ${b.nutrientError.toExponential(2)}。这是单养分的抽象生态模型；不表示真实分子的元素组成。</p><p>食物网络来自实际摄食。结构基因仍使用有限的发育规则，演化不保证产生复杂生命；当前生态参数是经过实验调整的游戏常数。</p></details></section>`;
}
